html.content:
%%[ SET @firstname = AttributeValue("FirstName") ]%%

<!DOCTYPE html>
<html>
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <style>
      body {
        font-family: Arial, Helvetica, sans-serif;
        background: #fafafa;
        margin: 0;
        padding: 40px 0;
      }
      .card {
        background: #ffffff;
        width: 100%;
        max-width: 480px;
        margin: auto;
        padding: 40px 30px;
        border-radius: 16px;
        text-align: center;
        box-shadow: 0 4px 16px rgba(0,0,0,0.08);
      }
      h1 {
        font-size: 24px;
        color: #333333;
        margin: 0 0 10px 0;
      }
      p {
        font-size: 17px;
        color: #555555;
        margin: 0;
      }
      .footer {
        font-size: 12px;
        color: #888888;
        text-align: center;
        margin-top: 30px;
        line-height: 1.4;
      }
    </style>
  </head>

  <body>
    <div class="card">
      <h1>Ciao %%=v(@firstname)=%% 🌼</h1>
      <p>Benvenuto! Siamo felici di averti qui.</p>
    </div>

    <!-- REQUIRED FOOTER -->
    <div class="footer">
      This email was sent by:<br>
      %%Member_Busname%%<br>
      %%Member_Addr%%<br>
      %%Member_City%%, %%Member_State%%, %%Member_PostalCode%%, %%Member_Country%%
    </div>
  </body>
</html>

